import { closeDatabase, openDatabase } from "../../src/server/db/database.js";
import { runMigrations } from "../../src/server/db/migrate.js";
import { createFastifyTestHarness } from "../helpers/fastify.js";

describe("durable bookmark capture", () => {
  it("saves a fallback immediately and survives a database reopen", async () => {
    const harness = await createFastifyTestHarness();
    const response = await harness.injectJson({
      method: "POST",
      url: "/api/bookmarks",
      payload: { address: "https://example.com/long-story", unread: true },
    });
    expect(response.statusCode).toBe(201);
    expect(response.json()).toMatchObject({
      address: "https://example.com/long-story",
      title: "Long story",
      titleProvenance: "fallback",
      metadataStatus: "pending",
      unread: true,
    });

    const id = response.json().id as number;
    const databasePath = harness.testDatabase.databasePath;
    await harness.app.close();
    closeDatabase(harness.testDatabase.database);

    const reopened = openDatabase(databasePath);
    runMigrations(reopened);
    expect(reopened.prepare("SELECT id, is_unread FROM bookmarks WHERE id = ?").get(id)).toEqual({ id, is_unread: 1 });
    closeDatabase(reopened);
    harness.testDatabase.cleanup();
  });

  it("keeps one row under normalized duplicate attempts, including archived rows", async () => {
    const harness = await createFastifyTestHarness();
    try {
      const first = await harness.injectJson({ method: "POST", url: "/api/bookmarks", payload: { address: "https://example.com/item#one" } });
      const id = first.json().id as number;
      harness.testDatabase.database.prepare("UPDATE bookmarks SET archived_at = ? WHERE id = ?").run("2026-09-17T00:00:00.000Z", id);

      const second = await harness.injectJson({ method: "POST", url: "/api/bookmarks", payload: { address: "https://EXAMPLE.com:443/item#two" } });
      expect(second.statusCode).toBe(409);
      expect(second.json()).toMatchObject({ existingBookmarkId: id, existingScope: "archived" });
      expect(harness.testDatabase.database.prepare("SELECT count(*) AS count FROM bookmarks").get()).toEqual({ count: 1 });
    } finally {
      await harness.close();
    }
  });

  it("marks supplied text as user-authored so enrichment cannot clobber it", async () => {
    const harness = await createFastifyTestHarness();
    try {
      const response = await harness.injectJson({
        method: "POST",
        url: "/api/bookmarks",
        payload: { address: "https://example.com/custom", title: "My title", description: "My description" },
      });
      expect(response.statusCode).toBe(201);
      expect(response.json()).toMatchObject({ title: "My title", titleProvenance: "user", description: "My description", descriptionProvenance: "user" });

      const row = harness.testDatabase.database.prepare("SELECT title_provenance, description_provenance, address_revision FROM bookmarks WHERE id = ?").get(response.json().id);
      expect(row).toEqual({ title_provenance: "user", description_provenance: "user", address_revision: 1 });
    } finally {
      await harness.close();
    }
  });
});

