}

.brand > span:last-child {
  display: flex;
  flex-direction: column;
}

.brand strong {
  font-family: var(--font-display);
  font-size: 1.2rem;
  line-height: 1.15;
}

.brand small {
  color: var(--ink-600);
  font-size: 0.72rem;
}

