  display: inline-grid;
  flex: 0 0 auto;
  width: 2.45rem;
  height: 2.45rem;
  place-items: center;
  border: 1px solid #bad0bc;
  border-radius: 50%;
  background: var(--leaf-100);
  color: var(--leaf-700);
}

.brand-mark svg {
  width: 1.7rem;
  height: 1.7rem;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.5;
}

.button {
  display: inline-flex;
  min-height: 2.65rem;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 0.62rem 1.05rem;
  font-weight: 700;
  line-height: 1.1;
  cursor: pointer;
  transition: 140ms ease;
  transition-property: color, background-color, border-color, box-shadow, transform;
}

.button:not(:disabled):active {
  transform: translateY(1px);
}

.button:disabled {
  cursor: not-allowed;
  opacity: 0.56;
}

.button--primary {
  background: var(--leaf-700);
  color: white;
  box-shadow: 0 4px 0 #244a34;
}

.button--primary:not(:disabled):hover {
  background: #254f38;
}

.button--secondary {
  border-color: var(--line-strong);
  background: var(--surface-raised);
  color: var(--ink-800);
}

.button--secondary:not(:disabled):hover,
.button--quiet:not(:disabled):hover {
  background: var(--paper-deep);
}

.button--quiet {
  background: transparent;
  color: var(--ink-800);
}

.button--danger {
  background: var(--danger-700);
  color: white;
}

.button--small {
  min-height: 2.25rem;
  padding: 0.45rem 0.75rem;
  font-size: 0.875rem;
}

.button__spinner {
  width: 1em;
  height: 1em;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: spin 700ms linear infinite;
}

.app-layout {
  display: grid;
  grid-template-columns: minmax(12.5rem, 15rem) minmax(0, 1fr);
  width: min(100%, 96rem);
  min-height: calc(100vh - 8.5rem);
  margin: 0 auto;
}

.sidebar {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 2rem;
  padding: 2rem 1.25rem 2rem clamp(1rem, 3vw, 2rem);
  border-right: 1px solid var(--line);
}

.nav-label,
.eyebrow {
  margin: 0 0 0.6rem;
  color: var(--leaf-700);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.nav-list {
  display: grid;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.nav-link {
  display: flex;
  min-height: 2.75rem;
  align-items: center;
  border-radius: var(--radius-small);
  padding: 0.55rem 0.75rem;
  color: var(--ink-600);
  font-weight: 650;
  text-decoration: none;
}

.nav-link:hover {
  background: rgba(225, 237, 223, 0.6);
  color: var(--leaf-700);
}

.nav-link--active {
  background: var(--leaf-100);
  color: var(--leaf-700);
  box-shadow: inset 3px 0 var(--leaf-600);
}

.sidebar-note {
  padding: 1rem;
  border: 1px solid #ead5a9;
  border-radius: var(--radius-medium);
  background: var(--sun-100);
  color: #6b5125;
  font-size: 0.82rem;
}

.sidebar-note span {
  color: #ad781b;
}

.sidebar-note p {
  margin: 0.4rem 0 0;
}

.main-content {
  min-width: 0;
  padding: clamp(1.6rem, 4vw, 3.75rem);
}

.page-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 1.5rem;
  margin-bottom: 2rem;
}

.page-heading h1,
.fatal-state h1 {
  max-width: 17ch;
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(2rem, 4.2vw, 3.6rem);
  font-weight: 650;
  letter-spacing: -0.035em;
  line-height: 1.04;
}

.collection-panel {
