}

.nav-label,
.eyebrow {
  margin: 0 0 0.6rem;
  color: var(--leaf-700);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.nav-list {
  display: grid;
  gap: 0.35rem;
  margin: 0;
  padding: 0;
