  input: Uint8Array,
  options: ProcessIconOptions = {},
): Promise<ProcessedIcon | null> {
  try {
    return await processIcon(input, options);
  } catch (error) {
    if (error instanceof IconProcessingError) return null;
    throw error;
  }
}

