import { randomUUID } from "node:crypto";
import { expect, test, type APIResponse, type Page } from "@playwright/test";

interface SeedBookmark {
  address: string;
  title: string;
  description: string;
  favorite: boolean;
  unread: boolean;
}

async function seedBookmark(page: Page, input: SeedBookmark): Promise<void> {
  const response: APIResponse = await page.request.post("/api/bookmarks", { data: input });
  expect(response.status(), await response.text()).toBe(201);
}

async function submitSearch(page: Page, query: string): Promise<void> {
  const search = page.getByRole("searchbox", { name: "Search bookmarks" });
  await search.fill(query);
  await page.getByRole("button", { name: "Search", exact: true }).click();
  await expect.poll(() => new URL(page.url()).searchParams.get("q")).toBe(query);
}

async function visibleBookmarkNames(page: Page): Promise<string[]> {
  const articles = page
    .getByRole("region", { name: "Bookmarks", exact: true })
    .getByRole("article");
  return articles.evaluateAll((elements) =>
    elements.map((element) => element.getAttribute("aria-label") ?? ""),
  );
}

async function expectResults(page: Page, expectedTitles: string[]): Promise<void> {
  await expect
    .poll(() => visibleBookmarkNames(page), { message: "visible bookmark result titles" })
    .toEqual(expectedTitles);
}

test("search expressions, filters, errors, URL state, clearing, and sorts compose", async ({
  page,
}) => {
  const token = `search${randomUUID().replaceAll("-", "").slice(0, 12)}`;
  const alpha = `${token} Alpha Climate`;
  const bravo = `${token} Bravo Climate`;
  const charlie = `${token} Charlie Ocean`;
  const delta = `${token} Delta Orchard`;

  const seeds: SeedBookmark[] = [
    {
      address: `https://search-fixture.invalid/${token}/alpha`,
      title: alpha,
      description: "Crimson tide field notes",
      favorite: true,
      unread: true,
    },
    {
      address: `https://search-fixture.invalid/${token}/bravo`,
      title: bravo,
      description: "Solar systems briefing",
      favorite: true,
      unread: false,
    },
    {
      address: `https://search-fixture.invalid/${token}/charlie`,
      title: charlie,
      description: "Crimson meadow observations",
      favorite: false,
      unread: true,
    },
    {
      address: `https://search-fixture.invalid/${token}/delta`,
      title: delta,
      description: "Tidal orchard atlas",
      favorite: false,
      unread: false,
    },
  ];

  await page.goto("/");
  await expect(page.locator('[data-harness-ready="true"]')).toBeVisible();
  for (const seed of seeds) await seedBookmark(page, seed);
  await page.reload();
  await expect(page.locator('[data-harness-ready="true"]')).toBeVisible();

  await test.step("ordinary partial terms use implicit AND and survive reload through the URL", async () => {
    const query = `${token} climat`;
    await submitSearch(page, query);
    await expectResults(page, [bravo, alpha]);

    await page.reload();
    await expect(page.locator('[data-harness-ready="true"]')).toBeVisible();
    await expect(page.getByRole("searchbox", { name: "Search bookmarks" })).toHaveValue(query);
    await expectResults(page, [bravo, alpha]);
  });

  await test.step("quoted phrases stay in one field and explicit AND is accepted", async () => {
    await submitSearch(page, `"crimson tide" AND ${token}`);
    await expectResults(page, [alpha]);
  });

  await test.step("OR returns either matching branch", async () => {
    await submitSearch(page, `${token} ocean OR ${token} orchard`);
    await expectResults(page, [delta, charlie]);
  });

  await test.step("invalid syntax is actionable and does not replace the active query", async () => {
    const activeQuery = new URL(page.url()).searchParams.get("q");
    const search = page.getByRole("searchbox", { name: "Search bookmarks" });
    await search.fill('"unfinished');
    await expect(page.getByRole("alert")).toContainText(/close the quoted phrase/i);
    await expect(page.getByRole("button", { name: "Search", exact: true })).toBeDisabled();
    await expect.poll(() => new URL(page.url()).searchParams.get("q")).toBe(activeQuery);
  });

  await test.step("sort choices are URL-backed and reorder the same result set", async () => {
    await submitSearch(page, token);
    const sort = page.getByRole("combobox", { name: "Sort bookmarks" });

    await sort.selectOption("title_asc");
    await expect.poll(() => new URL(page.url()).searchParams.get("sort")).toBe("title_asc");
    await expectResults(page, [alpha, bravo, charlie, delta]);

    await sort.selectOption("created_desc");
    await expect.poll(() => new URL(page.url()).searchParams.get("sort")).toBeNull();
    await expectResults(page, [delta, charlie, bravo, alpha]);
  });

  await test.step("favorite and reading filters combine without losing the search", async () => {
    await page
      .getByRole("combobox", { name: "Favorite filter" })
      .selectOption({ label: "Favorites only" });
    await page
      .getByRole("combobox", { name: "Reading filter" })
      .selectOption({ label: "Read Later" });

    await expect.poll(() => new URL(page.url()).searchParams.get("favorite")).toBe("true");
    await expect.poll(() => new URL(page.url()).searchParams.get("unread")).toBe("true");
    await expectResults(page, [alpha]);
  });

  await test.step("clear removes search and filter criteria from controls and URL", async () => {
    await page.getByRole("button", { name: "Clear search and filters" }).click();
    await expect(page.getByRole("searchbox", { name: "Search bookmarks" })).toHaveValue("");
    await expect(page.getByRole("combobox", { name: "Favorite filter" })).toHaveValue("any");
    await expect(page.getByRole("combobox", { name: "Reading filter" })).toHaveValue("any");
    await expect.poll(() => new URL(page.url()).searchParams.get("q")).toBeNull();
    await expect.poll(() => new URL(page.url()).searchParams.get("favorite")).toBeNull();
    await expect.poll(() => new URL(page.url()).searchParams.get("unread")).toBeNull();
  });
});
import {
  BookmarkNotFoundError,
  BookmarkRepository,
} from "../../src/server/repositories/bookmark-repository.js";
import { BookmarkStateService } from "../../src/server/services/bookmarks/bookmark-state-service.js";
import { type TestDatabase, withTestDatabase } from "../helpers/database.js";
import { withFastifyTestHarness } from "../helpers/fastify.js";

const FIRST_TIME = "2026-09-17T12:00:00.000Z";
const SECOND_TIME = "2026-09-17T12:05:00.000Z";

function createBookmark(
  fixture: TestDatabase,
  values: { id: number; favorite?: boolean; unread?: boolean },
) {
  const repository = new BookmarkRepository(fixture.database);
  const address = `https://example.test/read-later/${values.id}`;
  return repository.create({
    input: {
      address,
      favorite: values.favorite,
      unread: values.unread,
    },
    address,
    normalizedAddress: address,
    fallbackTitle: `Bookmark ${values.id}`,
    now: FIRST_TIME,
  });
}

describe("Read Later repository state", () => {
  it("creates bookmarks as read unless Read Later is explicitly selected", async () => {
    await withTestDatabase((fixture) => {
      const read = createBookmark(fixture, { id: 1 });
      const unread = createBookmark(fixture, { id: 2, unread: true });

      expect(read.unread).toBe(false);
      expect(unread.unread).toBe(true);
      expect(new BookmarkRepository(fixture.database).scopeCounts()).toEqual({
        active: 2,
        readLater: 1,
        archived: 0,
      });
    });
  });

  it("atomically marks read and unread without changing favorite or archive state", async () => {
    await withTestDatabase((fixture) => {
      const created = createBookmark(fixture, { id: 1, favorite: true });
      const repository = new BookmarkRepository(fixture.database);
      const service = new BookmarkStateService(repository, () => new Date(SECOND_TIME));

      const markedUnread = service.setUnread(created.id, true);
      expect(markedUnread).toMatchObject({
        id: created.id,
        favorite: true,
        unread: true,
        archived: false,
        updatedAt: SECOND_TIME,
      });
      expect(repository.scopeCounts().readLater).toBe(1);

      const markedRead = service.setUnread(created.id, false);
      expect(markedRead).toMatchObject({
        id: created.id,
        favorite: true,
        unread: false,
        archived: false,
      });
      expect(repository.scopeCounts().readLater).toBe(0);
    });
  });

  it("does not refresh updatedAt for an idempotent reading-state request", async () => {
    await withTestDatabase((fixture) => {
      const created = createBookmark(fixture, { id: 1, unread: true });
      const service = new BookmarkStateService(
        new BookmarkRepository(fixture.database),
        () => new Date(SECOND_TIME),
      );

      expect(service.setUnread(created.id, true).updatedAt).toBe(FIRST_TIME);
    });
  });

  it("reports a missing bookmark without modifying another bookmark", async () => {
    await withTestDatabase((fixture) => {
      const existing = createBookmark(fixture, { id: 1, unread: true });
      const repository = new BookmarkRepository(fixture.database);
      const service = new BookmarkStateService(repository, () => new Date(SECOND_TIME));

      expect(() => service.setUnread(existing.id + 100, false)).toThrow(BookmarkNotFoundError);
      expect(repository.get(existing.id)).toMatchObject({ unread: true, updatedAt: FIRST_TIME });
    });
  });

  it("defines Read Later as active and unread while archive retains reading/favorite state", async () => {
    await withTestDatabase((fixture) => {
      const retained = createBookmark(fixture, { id: 1, favorite: true, unread: true });
      createBookmark(fixture, { id: 2, unread: true });
      createBookmark(fixture, { id: 3 });
      const repository = new BookmarkRepository(fixture.database);

      expect(repository.scopeCounts()).toEqual({ active: 3, readLater: 2, archived: 0 });

      fixture.database
        .prepare("UPDATE bookmarks SET archived_at = ?, updated_at = ? WHERE id = ?")
        .run(SECOND_TIME, SECOND_TIME, retained.id);
      expect(repository.get(retained.id)).toMatchObject({
        favorite: true,
        unread: true,
        archived: true,
      });
      expect(repository.scopeCounts()).toEqual({ active: 2, readLater: 1, archived: 1 });

      fixture.database
        .prepare("UPDATE bookmarks SET archived_at = NULL, updated_at = ? WHERE id = ?")
        .run(SECOND_TIME, retained.id);
      expect(repository.get(retained.id)).toMatchObject({
        favorite: true,
        unread: true,
        archived: false,
      });
      expect(repository.scopeCounts()).toEqual({ active: 3, readLater: 2, archived: 0 });
    });
  });
});

describe("Read Later HTTP behavior", () => {
  it("defaults capture to read and honors an explicit Read Later choice", async () => {
    await withFastifyTestHarness(async ({ injectJson }) => {
      const read = await injectJson({
        method: "POST",
        url: "/api/bookmarks",
        payload: { address: "https://example.com/already-read" },
      });
      const unread = await injectJson({
        method: "POST",
        url: "/api/bookmarks",
        payload: { address: "https://example.com/read-this", unread: true },
      });

      expect(read.statusCode).toBe(201);
      expect(read.json()).toMatchObject({ unread: false });
      expect(unread.statusCode).toBe(201);
      expect(unread.json()).toMatchObject({ unread: true });
    });
  });

  it("moves bookmarks into and out of the Read Later scope independently of favorite", async () => {
    await withFastifyTestHarness(async ({ injectJson }) => {
      const favorite = await injectJson({
        method: "POST",
        url: "/api/bookmarks",
        payload: { address: "https://example.com/favorite", favorite: true },
      });
      const ordinary = await injectJson({
        method: "POST",
        url: "/api/bookmarks",
        payload: { address: "https://example.com/ordinary", unread: true },
      });

      const markUnread = await injectJson({
        method: "PATCH",
        url: `/api/bookmarks/${favorite.json().id}`,
        payload: { unread: true },
      });
      expect(markUnread.statusCode).toBe(200);
      expect(markUnread.json()).toMatchObject({ favorite: true, unread: true, archived: false });

      const listed = await injectJson({
        method: "GET",
        url: "/api/bookmarks?scope=read_later&sort=created_asc",
      });
      expect(listed.statusCode).toBe(200);
      expect(listed.json().items.map((bookmark: { id: number }) => bookmark.id)).toEqual([
        favorite.json().id,
        ordinary.json().id,
      ]);

      const markRead = await injectJson({
        method: "PATCH",
        url: `/api/bookmarks/${favorite.json().id}`,
        payload: { unread: false },
      });
      expect(markRead.statusCode).toBe(200);
      expect(markRead.json()).toMatchObject({ favorite: true, unread: false, archived: false });

      const readLater = await injectJson({
        method: "GET",
        url: "/api/bookmarks?scope=read_later",
      });
      const active = await injectJson({ method: "GET", url: "/api/bookmarks?scope=active" });
      expect(readLater.json().items.map((bookmark: { id: number }) => bookmark.id)).toEqual([
        ordinary.json().id,
      ]);
      expect(active.json().items.map((bookmark: { id: number }) => bookmark.id)).toContain(
        favorite.json().id,
      );
    });
  });
});
