import { type FormEvent, useState } from "react";
import { Button, Status, TextAreaField, TextField } from "../../components";
import {
  ApiError,
  api,
  type Bookmark,
  type BookmarkApiClient,
  type BookmarkPatch,
  type Scope,
} from "../../lib/api";
import { NoteEditor } from "./NoteEditor";

export interface BookmarkEditorProps {
  bookmark: Bookmark;
  client?: BookmarkApiClient | undefined;
  onSaved: (bookmark: Bookmark) => void;
  onCancel: () => void;
  onDuplicate: (bookmarkId: number, scope?: Scope) => void;
}

function normalizeTags(value: string): string[] {
  const result: string[] = [];
  const seen = new Set<string>();
  for (const raw of value.split(",")) {
    const tag = raw.trim();
    const key = tag.toLocaleLowerCase();
    if (!tag || seen.has(key)) continue;
    seen.add(key);
    result.push(tag);
  }
  return result;
}

export function BookmarkEditor({
  bookmark,
  client = api,
  onSaved,
  onCancel,
  onDuplicate,
}: BookmarkEditorProps) {
  const [address, setAddress] = useState(bookmark.address);
  const [title, setTitle] = useState(bookmark.title);
  const [description, setDescription] = useState(bookmark.description);
  const [tags, setTags] = useState(bookmark.tags.map((tag) => tag.name).join(", "));
  const [noteMarkdown, setNoteMarkdown] = useState(bookmark.noteMarkdown);
  const [acceptTitle, setAcceptTitle] = useState(false);
  const [acceptDescription, setAcceptDescription] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSaving(true);
    setError(null);
    const controller = new AbortController();
    try {
      const patch: BookmarkPatch = {
        ...(address.trim() !== bookmark.address ? { address: address.trim() } : {}),
        ...(!acceptTitle && title.trim() !== bookmark.title ? { title: title.trim() } : {}),
        ...(!acceptDescription && description.trim() !== bookmark.description
          ? { description: description.trim() }
          : {}),
        ...(noteMarkdown !== bookmark.noteMarkdown ? { noteMarkdown } : {}),
        ...(tags !== bookmark.tags.map((tag) => tag.name).join(", ")
          ? { tags: normalizeTags(tags) }
          : {}),
        ...(acceptTitle ? { acceptRetrievedTitle: true } : {}),
        ...(acceptDescription ? { acceptRetrievedDescription: true } : {}),
      };
      if (Object.keys(patch).length === 0) {
        onSaved(bookmark);
        return;
      }
      const updated = await client.updateBookmark(bookmark.id, patch, {
        signal: controller.signal,
      });
      onSaved(updated);
    } catch (cause) {
      if (
        cause instanceof ApiError &&
        cause.problem.code === "DUPLICATE_BOOKMARK" &&
        "existingBookmarkId" in cause.problem
      ) {
        onDuplicate(cause.problem.existingBookmarkId, cause.problem.existingScope);
      } else {
        setError(
          cause instanceof ApiError
            ? cause.problem.message
            : "The bookmark could not be updated. Please try again.",
        );
      }
    } finally {
      setSaving(false);
    }
  }

  return (
    <form className="bookmark-editor" onSubmit={submit}>
      <TextField
        id="bookmark-edit-address"
        label="Web address"
        type="url"
        required
        value={address}
        onChange={(event) => setAddress(event.currentTarget.value)}
      />
      <div className="bookmark-editor__candidate-field">
        <TextField
          id="bookmark-edit-title"
          label="Title"
          required
          value={title}
          onChange={(event) => {
            setAcceptTitle(false);
            setTitle(event.currentTarget.value);
          }}
        />
        {bookmark.retrievedTitleCandidate && bookmark.retrievedTitleCandidate !== bookmark.title ? (
          <div className="metadata-candidate">
            <span>Retrieved suggestion: {bookmark.retrievedTitleCandidate}</span>
            <Button
              size="small"
              variant="quiet"
              onClick={() => {
                setTitle(bookmark.retrievedTitleCandidate ?? title);
                setAcceptTitle(true);
              }}
            >
              Use retrieved title
            </Button>
          </div>
        ) : null}
      </div>
      <div className="bookmark-editor__candidate-field">
        <TextAreaField
          id="bookmark-edit-description"
          label="Description"
          rows={3}
          value={description}
          onChange={(event) => {
            setAcceptDescription(false);
            setDescription(event.currentTarget.value);
          }}
        />
        {bookmark.retrievedDescriptionCandidate &&
        bookmark.retrievedDescriptionCandidate !== bookmark.description ? (
          <div className="metadata-candidate">
            <span>Retrieved suggestion: {bookmark.retrievedDescriptionCandidate}</span>
            <Button
              size="small"
              variant="quiet"
              onClick={() => {
                setDescription(bookmark.retrievedDescriptionCandidate ?? description);
                setAcceptDescription(true);
              }}
            >
              Use retrieved description
            </Button>
          </div>
        ) : null}
      </div>
      <TextField
        id="bookmark-edit-tags"
        label="Tags"
        value={tags}
        hint="Separate tags with commas. Capitalization-only duplicates are combined."
        onChange={(event) => setTags(event.currentTarget.value)}
      />
      <NoteEditor value={noteMarkdown} onChange={setNoteMarkdown} />
      {error ? <Status tone="error">{error}</Status> : null}
      <div className="bookmark-editor__actions">
        <Button variant="quiet" onClick={onCancel}>
          Cancel
        </Button>
        <Button type="submit" variant="primary" busy={saving} busyLabel="Saving changes…">
          Save changes
        </Button>
      </div>
    </form>
  );
}
import { useId, useRef, useState } from "react";
import { Button } from "../../components";
import { FormattedNote } from "./FormattedNote";

export interface NoteEditorProps {
  value: string;
  onChange: (value: string) => void;
  initialMode?: "source" | "preview";
}

type Wrapper = { before: string; after: string; placeholder: string };

const wrappers = {
  heading: { before: "## ", after: "", placeholder: "Heading" },
  bold: { before: "**", after: "**", placeholder: "bold text" },
  italic: { before: "*", after: "*", placeholder: "italic text" },
  bullets: { before: "- ", after: "", placeholder: "list item" },
  numbers: { before: "1. ", after: "", placeholder: "list item" },
  link: { before: "[", after: "](https://example.com)", placeholder: "link text" },
  code: { before: "`", after: "`", placeholder: "code" },
} satisfies Record<string, Wrapper>;

export function NoteEditor({ value, onChange, initialMode = "source" }: NoteEditorProps) {
  const [mode, setMode] = useState(initialMode);
  const [showHelp, setShowHelp] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const id = useId();

  function apply(wrapper: Wrapper) {
    const textarea = textareaRef.current;
    if (!textarea) return;
    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selected = value.slice(start, end) || wrapper.placeholder;
    const replacement = `${wrapper.before}${selected}${wrapper.after}`;
    onChange(`${value.slice(0, start)}${replacement}${value.slice(end)}`);
    textarea.focus();
    window.requestAnimationFrame(() => {
      const selectionStart = start + wrapper.before.length;
      textarea.setSelectionRange(selectionStart, selectionStart + selected.length);
    });
  }

  return (
    <section className="note-editor" aria-labelledby={`${id}-label`}>
      <div className="note-editor__heading">
        <label id={`${id}-label`} htmlFor={`${id}-source`}>
          Formatted note
        </label>
        <div className="note-editor__modes">
          <Button
            size="small"
            variant={mode === "source" ? "secondary" : "quiet"}
            aria-pressed={mode === "source"}
            onClick={() => setMode("source")}
          >
            Edit source
          </Button>
          <Button
            size="small"
            variant={mode === "preview" ? "secondary" : "quiet"}
            aria-pressed={mode === "preview"}
            onClick={() => setMode("preview")}
          >
            Preview note
          </Button>
        </div>
      </div>

      {mode === "source" ? (
        <>
          <div className="note-toolbar" role="toolbar" aria-label="Note formatting">
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.heading)}>
              Heading
            </Button>
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.bold)}>
              Bold
            </Button>
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.italic)}>
              Italic
            </Button>
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.bullets)}>
              Bulleted list
            </Button>
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.numbers)}>
              Numbered list
            </Button>
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.link)}>
              Link
            </Button>
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.code)}>
              Inline code
            </Button>
          </div>
          <textarea
            ref={textareaRef}
            id={`${id}-source`}
            className="text-input text-area note-editor__source"
            aria-label="Note source"
            value={value}
            onChange={(event) => onChange(event.currentTarget.value)}
          />
        </>
      ) : (
        <section className="note-editor__preview" aria-label="Formatted note preview">
          {value.trim() ? (
            <FormattedNote markdown={value} />
          ) : (
            <p className="note-editor__empty">Nothing to preview yet.</p>
          )}
        </section>
      )}

      <Button
        size="small"
        variant="quiet"
        aria-expanded={showHelp}
        onClick={() => setShowHelp((current) => !current)}
      >
        Formatting help
      </Button>
      {showHelp ? (
        <p className="note-editor__help">
          Headings, bold, italic, ordered and unordered lists, links, and inline code are supported.
          Raw HTML, images, and active content are not displayed.
        </p>
      ) : null}
    </section>
  );
}
