export interface NoteEditorProps {
  value: string;
  onChange: (value: string) => void;
  initialMode?: "source" | "preview";
}

type Wrapper = { before: string; after: string; placeholder: string };

const wrappers = {
  heading: { before: "## ", after: "", placeholder: "Heading" },
  bold: { before: "**", after: "**", placeholder: "bold text" },
  italic: { before: "*", after: "*", placeholder: "italic text" },
  bullets: { before: "- ", after: "", placeholder: "list item" },
  numbers: { before: "1. ", after: "", placeholder: "list item" },
  link: { before: "[", after: "](https://example.com)", placeholder: "link text" },
  code: { before: "`", after: "`", placeholder: "code" },
} satisfies Record<string, Wrapper>;

export function NoteEditor({ value, onChange, initialMode = "source" }: NoteEditorProps) {
  const [mode, setMode] = useState(initialMode);
  const [showHelp, setShowHelp] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const id = useId();

  function apply(wrapper: Wrapper) {
    const textarea = textareaRef.current;
    if (!textarea) return;
    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selected = value.slice(start, end) || wrapper.placeholder;
    const replacement = `${wrapper.before}${selected}${wrapper.after}`;
    onChange(`${value.slice(0, start)}${replacement}${value.slice(end)}`);
    textarea.focus();
    window.requestAnimationFrame(() => {
      const selectionStart = start + wrapper.before.length;
      textarea.setSelectionRange(selectionStart, selectionStart + selected.length);
    });
  }

  return (
    <section className="note-editor" aria-labelledby={`${id}-label`}>
      <div className="note-editor__heading">
        <label id={`${id}-label`} htmlFor={`${id}-source`}>
          Formatted note
        </label>
        <div className="note-editor__modes">
          <Button
            size="small"
            variant={mode === "source" ? "secondary" : "quiet"}
            aria-pressed={mode === "source"}
            onClick={() => setMode("source")}
          >
            Edit source
          </Button>
          <Button
            size="small"
            variant={mode === "preview" ? "secondary" : "quiet"}
            aria-pressed={mode === "preview"}
            onClick={() => setMode("preview")}
          >
            Preview note
          </Button>
        </div>
      </div>

      {mode === "source" ? (
        <>
          <div className="note-toolbar" role="toolbar" aria-label="Note formatting">
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.heading)}>
              Heading
            </Button>
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.bold)}>
              Bold
            </Button>
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.italic)}>
              Italic
            </Button>
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.bullets)}>
              Bulleted list
            </Button>
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.numbers)}>
              Numbered list
            </Button>
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.link)}>
              Link
            </Button>
            <Button size="small" variant="quiet" onClick={() => apply(wrappers.code)}>
              Inline code
            </Button>
          </div>
          <textarea
            ref={textareaRef}
            id={`${id}-source`}
            className="text-input text-area note-editor__source"
            aria-label="Note source"
            value={value}
            onChange={(event) => onChange(event.currentTarget.value)}
          />
        </>
      ) : (
        <section className="note-editor__preview" aria-label="Formatted note preview">
          {value.trim() ? (
            <FormattedNote markdown={value} />
          ) : (
            <p className="note-editor__empty">Nothing to preview yet.</p>
          )}
        </section>
      )}

      <Button
        size="small"
        variant="quiet"
        aria-expanded={showHelp}
        onClick={() => setShowHelp((current) => !current)}
      >
        Formatting help
      </Button>
      {showHelp ? (
        <p className="note-editor__help">
          Headings, bold, italic, ordered and unordered lists, links, and inline code are supported.
          Raw HTML, images, and active content are not displayed.
        </p>
      ) : null}
    </section>
  );
}
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import ReactMarkdown from "react-markdown";

export interface FormattedNoteProps {
  markdown: string;
  className?: string;
}

const allowedElements = [
  "h1",
  "h2",
  "h3",
  "h4",
  "h5",
  "h6",
  "p",
  "strong",
  "em",
  "ul",
  "ol",
  "li",
  "a",
  "code",
] as const;

function safeLink(href: string | undefined): boolean {
  if (!href) return false;
  if (href.startsWith("#") || href.startsWith("/")) return true;
  try {
    const url = new URL(href);
    return url.protocol === "http:" || url.protocol === "https:" || url.protocol === "mailto:";
  } catch {
    return false;
  }
}

function SafeAnchor({ href, children }: ComponentPropsWithoutRef<"a"> & { children?: ReactNode }) {
  if (!safeLink(href)) return <span>{children}</span>;
  return (
    <a href={href} target="_blank" rel="noopener noreferrer">
      {children}
    </a>
  );
}

export function FormattedNote({ markdown, className = "" }: FormattedNoteProps) {
  if (!markdown.trim()) return null;
  return (
    <div className={`formatted-note ${className}`.trim()}>
      <ReactMarkdown
        skipHtml
        allowedElements={[...allowedElements]}
        unwrapDisallowed
        urlTransform={(url) => (safeLink(url) ? url : "")}
        components={{ a: SafeAnchor }}
      >
        {markdown}
      </ReactMarkdown>
    </div>
  );
}
import { useState } from "react";
import { Button, Status } from "../../components";
import { api, type Bookmark, type BookmarkApiClient } from "../../lib/api";

export interface BookmarkActionsProps {
  bookmark: Bookmark;
  client?: BookmarkApiClient | undefined;
  onUpdated: (bookmark: Bookmark, outcome?: string) => void;
}

type PendingAction = "favorite" | "archive" | "refresh" | null;

export function BookmarkActions({ bookmark, client = api, onUpdated }: BookmarkActionsProps) {
  const [pending, setPending] = useState<PendingAction>(null);
  const [outcome, setOutcome] = useState("");
  const [failed, setFailed] = useState(false);

  async function patch(
    action: Exclude<PendingAction, "refresh" | null>,
    change: { favorite: boolean } | { archived: boolean },
    message: string,
  ) {
    setPending(action);
    setFailed(false);
    try {
      const updated = await client.updateBookmark(bookmark.id, change);
      const retention = "archived" in change && bookmark.unread ? " Read Later retained." : "";
      const result = `${message}${retention}`;
      setOutcome(result);
      onUpdated(updated, result);
    } catch {
      setFailed(true);
      setOutcome("The bookmark could not be changed. Please try again.");
    } finally {
      setPending(null);
    }
  }

  async function refresh() {
    setPending("refresh");
    setFailed(false);
    try {
      await client.refreshBookmarkMetadata(bookmark.id);
      setOutcome("Page detail refresh started. Your custom text will be kept.");
    } catch {
      setFailed(true);
      setOutcome("Page details could not be refreshed. Please try again.");
    } finally {
      setPending(null);
    }
  }

  return (
    <section className="bookmark-actions" aria-label="Bookmark actions">
      <div className="bookmark-actions__buttons">
        <Button
          busy={pending === "favorite"}
          busyLabel="Updating…"
          onClick={() =>
            patch(
              "favorite",
              { favorite: !bookmark.favorite },
              bookmark.favorite ? "Removed from favorites." : "Added to favorites.",
            )
          }
        >
          {bookmark.favorite ? "Remove from favorites" : "Add to favorites"}
        </Button>
        <Button
          busy={pending === "archive"}
          busyLabel="Updating…"
          onClick={() =>
            patch(
              "archive",
              { archived: !bookmark.archived },
              bookmark.archived ? "Bookmark restored." : "Bookmark archived.",
            )
          }
        >
          {bookmark.archived ? "Restore bookmark" : "Archive bookmark"}
        </Button>
        <Button
          variant="quiet"
          busy={pending === "refresh"}
          busyLabel="Starting refresh…"
          onClick={refresh}
        >
          Refresh page details
        </Button>
      </div>
      <Status tone={failed ? "error" : outcome ? "success" : "neutral"}>
        {outcome || "Bookmark actions ready."}
      </Status>
    </section>
  );
}

