import { type FormEvent, useEffect, useState } from "react";
import { Button, Dialog, TextField } from "../../components";
import {
  ApiError,
  api,
  type BookmarkApiClient,
  type SavedView,
  type SearchCriteria,
} from "../../lib/api";

export interface SavedViewDialogProps {
  open: boolean;
  criteria: SearchCriteria;
  existing?: SavedView;
  client?: BookmarkApiClient;
  onSaved: (view: SavedView) => void;
  onClose: () => void;
}

export function SavedViewDialog({
  open,
  criteria,
  existing,
  client = api,
  onSaved,
  onClose,
}: SavedViewDialogProps) {
  const [name, setName] = useState(existing?.name ?? "");
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (open) {
      setName(existing?.name ?? "");
      setError(null);
    }
  }, [existing?.name, open]);

  async function submit(event: FormEvent) {
    event.preventDefault();
    const displayName = name.trim();
    if (!displayName) {
      setError("Enter a name for this view.");
      return;
    }
    const controller = new AbortController();
    setSaving(true);
    setError(null);
    const input = { ...criteria, name: displayName };
    try {
      const saved = existing
        ? await client.updateSavedView(existing.id, input, { signal: controller.signal })
        : await client.createSavedView(input, { signal: controller.signal });
      onSaved(saved);
      onClose();
    } catch (caught) {
      setError(
        caught instanceof ApiError
          ? caught.problem.message
          : "The saved view could not be stored. Please try again.",
      );
    } finally {
      setSaving(false);
    }
  }

  return (
    <Dialog
      open={open}
      title={existing ? "Update saved view" : "Save this view"}
      description="Saved views rerun these criteria against your current bookmarks."
      onClose={onClose}
    >
      <form className="saved-view-form" onSubmit={submit}>
        <TextField
          label="View name"
          value={name}
          required
          autoFocus
          error={error ?? undefined}
          onChange={(event) => setName(event.currentTarget.value)}
        />
        <div className="saved-view-summary">
          <strong>Criteria</strong>
          <span>{criteria.query || "All bookmarks"}</span>
          {criteria.tags.length ? <span>Tags: {criteria.tags.join(", ")}</span> : null}
          <span>Scope: {criteria.scope.replace("_", " ")}</span>
        </div>
        <div className="capture-form__actions">
          <Button variant="quiet" onClick={onClose}>
            Cancel
          </Button>
          <Button type="submit" variant="primary" busy={saving}>
            {existing ? "Update view" : "Save view"}
          </Button>
        </div>
      </form>
    </Dialog>
  );
}
import { useState } from "react";
import { Button, Dialog } from "../../components";
import type { SavedView } from "../../lib/api";

export interface SavedViewListProps {
  views: SavedView[];
  activeId?: number | null;
  onOpen: (view: SavedView) => void;
  onEdit: (view: SavedView) => void;
  onDelete: (view: SavedView) => void | Promise<void>;
}

export function SavedViewList({ views, activeId, onOpen, onEdit, onDelete }: SavedViewListProps) {
  const [deleting, setDeleting] = useState<SavedView | null>(null);

  if (!views.length) {
    return <p className="saved-views-empty">No saved views yet.</p>;
  }

  return (
    <>
      <ul className="saved-view-list">
        {views.map((view) => (
          <li key={view.id} className={activeId === view.id ? "saved-view--active" : ""}>
            <Button variant="quiet" onClick={() => onOpen(view)}>
              {view.name}
            </Button>
            <div>
              <Button
                size="small"
                variant="quiet"
                aria-label={`Edit ${view.name}`}
                onClick={() => onEdit(view)}
              >
                Edit
              </Button>
              <Button
                size="small"
                variant="quiet"
                aria-label={`Delete ${view.name}`}
                onClick={() => setDeleting(view)}
              >
                Delete
              </Button>
            </div>
          </li>
        ))}
      </ul>
      <Dialog
        open={deleting !== null}
        destructive
        title="Delete saved view?"
        description={
          deleting ? `Delete “${deleting.name}”? Your bookmarks will not be changed.` : undefined
        }
        onClose={() => setDeleting(null)}
        footer={
          <>
            <Button variant="quiet" onClick={() => setDeleting(null)}>
              Cancel
            </Button>
            <Button
              variant="danger"
              onClick={() => {
                const selected = deleting;
                setDeleting(null);
                if (selected) void onDelete(selected);
              }}
            >
              Delete saved view
            </Button>
          </>
        }
      />
    </>
  );
}
import { useCallback, useEffect, useState } from "react";
import { api, type BookmarkApiClient, type SavedView } from "../../lib/api";
import type { ViewState } from "../../lib/view-state";

export function applySavedViewToViewState(view: SavedView, current: ViewState): ViewState {
  return {
    ...current,
    scope: view.scope,
    query: view.query,
    tags: [...view.tags],
    favorite: view.favorite ?? null,
    unread: view.unread ?? null,
    sort: view.sort,
    savedViewId: view.id,
    bookmarkId: null,
    editing: false,
    cursor: null,
  };
}

export function useSavedViews(client: BookmarkApiClient = api) {
  const [views, setViews] = useState<SavedView[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const reload = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      setViews(await client.listSavedViews());
    } catch {
      setError("Saved views could not be loaded.");
    } finally {
      setLoading(false);
    }
  }, [client]);

  useEffect(() => {
    void reload();
  }, [reload]);

  const upsert = useCallback((view: SavedView) => {
    setViews((current) =>
      [...current.filter((candidate) => candidate.id !== view.id), view].sort((left, right) =>
        left.name.localeCompare(right.name),
      ),
    );
  }, []);

  const remove = useCallback(
    async (view: SavedView) => {
      await client.deleteSavedView(view.id);
      setViews((current) => current.filter((candidate) => candidate.id !== view.id));
    },
    [client],
  );

  return { views, loading, error, reload, upsert, remove };
}
// @vitest-environment happy-dom

import "@testing-library/jest-dom/vitest";
import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import type { BookmarkApiClient, SavedView, SearchCriteria } from "../../src/client/lib/api";
import { ApiError } from "../../src/client/lib/api";
import { SavedViewDialog } from "../../src/client/features/saved-views/SavedViewDialog";
import { SavedViewList } from "../../src/client/features/saved-views/SavedViewList";
import { applySavedViewToViewState } from "../../src/client/features/saved-views/useSavedViews";
import { DEFAULT_VIEW_STATE } from "../../src/client/lib/view-state";

const criteria: SearchCriteria = {
  scope: "archived",
  query: '"climate news" OR #research',
  tags: ["News", "Missing tag"],
  favorite: true,
  unread: null,
  sort: "title_asc",
};

const saved: SavedView = {
  ...criteria,
  id: 7,
  name: "Research watch",
  grammarVersion: 1,
  createdAt: "2026-09-17T12:00:00.000Z",
  updatedAt: "2026-09-17T12:00:00.000Z",
};

function client(overrides: Partial<BookmarkApiClient> = {}): BookmarkApiClient {
  return {
    getHealth: vi.fn(),
    previewMetadata: vi.fn(),
    listBookmarks: vi.fn(),
    createBookmark: vi.fn(),
    getBookmark: vi.fn(),
    updateBookmark: vi.fn(),
    deleteBookmark: vi.fn(),
    refreshBookmarkMetadata: vi.fn(),
    listTags: vi.fn(),
    createSelection: vi.fn(),
    clearSelection: vi.fn(),
    applyBulkAction: vi.fn(),
    listSavedViews: vi.fn(),
    createSavedView: vi.fn(),
    updateSavedView: vi.fn(),
    deleteSavedView: vi.fn(),
    ...overrides,
  } as BookmarkApiClient;
}

describe("saved views", () => {
  it("creates a named view from the exact current criteria and reports name conflicts", async () => {
    const user = userEvent.setup();
    const createSavedView = vi
      .fn()
      .mockRejectedValue(
        new ApiError(409, {
          code: "DUPLICATE_SAVED_VIEW_NAME",
          message: "That name already exists.",
          field: "name",
        }),
      );
    render(
      <SavedViewDialog
        open
        criteria={criteria}
        client={client({ createSavedView })}
        onSaved={vi.fn()}
        onClose={vi.fn()}
      />,
    );
    await user.type(screen.getByRole("textbox", { name: /view name/i }), "Research watch");
    await user.click(screen.getByRole("button", { name: /save view/i }));
    expect(createSavedView).toHaveBeenCalledWith(
      { ...criteria, name: "Research watch" },
      expect.objectContaining({ signal: expect.any(AbortSignal) }),
    );
    expect(await screen.findByRole("alert")).toHaveTextContent(/already exists/i);
  });

  it("renames or updates an existing view from current criteria", async () => {
    const user = userEvent.setup();
    const updateSavedView = vi.fn().mockResolvedValue({ ...saved, name: "Updated" });
    render(
      <SavedViewDialog
        open
        criteria={{ ...criteria, query: "current query" }}
        existing={saved}
        client={client({ updateSavedView })}
        onSaved={vi.fn()}
        onClose={vi.fn()}
      />,
    );
    const name = screen.getByRole("textbox", { name: /view name/i });
    await user.clear(name);
    await user.type(name, "Updated");
    await user.click(screen.getByRole("button", { name: /update view/i }));
    expect(updateSavedView).toHaveBeenCalledWith(
      saved.id,
      expect.objectContaining({ name: "Updated", query: "current query" }),
      expect.anything(),
    );
  });

  it("opens live criteria including a missing tag and clears prior selection/detail state", () => {
    expect(
      applySavedViewToViewState(saved, {
        ...DEFAULT_VIEW_STATE,
        bookmarkId: 99,
        editing: true,
        cursor: "old-page",
      }),
    ).toEqual(
      expect.objectContaining({
        scope: "archived",
        query: criteria.query,
        tags: ["News", "Missing tag"],
