  run: (harness: FastifyTestHarness) => T | Promise<T>,
  options: FastifyHarnessOptions = {},
): Promise<T> {
  const harness = await createFastifyTestHarness(options);
  try {
    return await run(harness);
  } finally {
    await harness.close();
  }
}

