import { classifyIpAddress, type ResolvedAddress, validatePublicAddresses } from "./ip-policy.js";

export const HTML_CONTENT_TYPES = ["text/html", "application/xhtml+xml"] as const;
export const RASTER_IMAGE_CONTENT_TYPES = [
