import ipaddr from "ipaddr.js";

export interface ResolvedAddress {
  address: string;
  family: 4 | 6;
}

export type IpClassification =
  | "public"
  | "invalid"
  | "unspecified"
  | "loopback"
  | "private"
  | "carrier-grade-nat"
  | "link-local"
  | "multicast"
  | "reserved";

function normalizedInput(address: string): string {
  const withoutBrackets =
    address.startsWith("[") && address.endsWith("]") ? address.slice(1, -1) : address;
  return withoutBrackets;
}

export function classifyIpAddress(address: string): IpClassification {
  const input = normalizedInput(address);
  if (input.includes("%") || !ipaddr.isValid(input)) return "invalid";

  const parsed = ipaddr.parse(input);
  if (parsed instanceof ipaddr.IPv6 && parsed.isIPv4MappedAddress()) {
    return classifyIpAddress(parsed.toIPv4Address().toString());
  }

  switch (parsed.range()) {
    case "unicast":
      return "public";
    case "unspecified":
      return "unspecified";
    case "loopback":
      return "loopback";
    case "private":
    case "uniqueLocal":
      return "private";
    case "carrierGradeNat":
      return "carrier-grade-nat";
    case "linkLocal":
      return "link-local";
    case "multicast":
      return "multicast";
    default:
      return "reserved";
  }
}

export function isPublicIpAddress(address: string): boolean {
  return classifyIpAddress(address) === "public";
}

export function validatePublicAddresses(
  addresses: readonly ResolvedAddress[],
): readonly ResolvedAddress[] {
  if (addresses.length === 0) {
    throw new Error("Destination did not resolve to an address");
  }

  for (const answer of addresses) {
    const parsed = normalizedInput(answer.address);
    if (!ipaddr.isValid(parsed)) {
      throw new Error("Destination resolved to an invalid address");
    }
    const expectedFamily = ipaddr.parse(parsed).kind() === "ipv4" ? 4 : 6;
    if (answer.family !== expectedFamily || !isPublicIpAddress(parsed)) {
      throw new Error("Destination resolved to a non-public address");
    }
  }

  return addresses;
}
import { createHash } from "node:crypto";
import sharp from "sharp";

const ACTIVE_CONTENT_TYPES = new Set([
  "image/svg+xml",
  "application/svg+xml",
  "application/xml",
  "text/xml",
  "text/html",
  "application/xhtml+xml",
]);

export type IconProcessingErrorCode =
  | "empty_input"
  | "input_too_large"
  | "active_content"
  | "unsupported_format"
  | "decode_failed"
  | "dimensions_exceeded";

export class IconProcessingError extends Error {
  constructor(
    public readonly code: IconProcessingErrorCode,
    message: string,
    options?: ErrorOptions,
  ) {
    super(message, options);
    this.name = "IconProcessingError";
  }
}

export interface ProcessIconOptions {
  contentType?: string | null;
  maxInputBytes?: number;
  maxInputPixels?: number;
  maxOutputDimension?: number;
}

export interface ProcessedIcon {
  contentHash: string;
  pngBytes: Buffer;
  width: number;
  height: number;
  byteLength: number;
  mimeType: "image/png";
}

type RasterSignature = "png" | "jpeg" | "gif" | "webp" | "ico";

function hasPrefix(input: Buffer, prefix: readonly number[]): boolean {
  return prefix.every((byte, index) => input[index] === byte);
}

export function detectRasterSignature(input: Uint8Array): RasterSignature | null {
  const bytes = Buffer.from(input.buffer, input.byteOffset, input.byteLength);
  if (bytes.length >= 8 && hasPrefix(bytes, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) {
    return "png";
  }
  if (bytes.length >= 3 && hasPrefix(bytes, [0xff, 0xd8, 0xff])) return "jpeg";
  if (
    bytes.length >= 6 &&
    (bytes.subarray(0, 6).toString("ascii") === "GIF87a" ||
      bytes.subarray(0, 6).toString("ascii") === "GIF89a")
  ) {
    return "gif";
  }
  if (
    bytes.length >= 12 &&
    bytes.subarray(0, 4).toString("ascii") === "RIFF" &&
    bytes.subarray(8, 12).toString("ascii") === "WEBP"
  ) {
    return "webp";
  }
  if (bytes.length >= 6 && hasPrefix(bytes, [0x00, 0x00, 0x01, 0x00])) return "ico";
  return null;
}

function normalizedContentType(value: string | null | undefined): string {
  return value?.split(";", 1)[0]?.trim().toLocaleLowerCase("en-US") ?? "";
}

export async function processIcon(
  input: Uint8Array,
