node -e "const fs=require('node:fs'); console.log(JSON.parse(fs.readFileSync('.harness/app.json','utf8')))"","workdir":"/work","yield_time_ms":30000,"max_output_tokens":30000});
text(r.output);

const patch = "*** Begin Patch
*** Update File: /work/.harness/app.json
@@
-{"kind":"application","port":4000,"path":"/","start_command":["npm","start"],"start_cwd":"/work"}
+{
+  "kind": "application",
+  "port": 4000,
+  "path": "/",
+  "start_command": ["npm", "start"],
+  "start_cwd": "/work"
+}
*** End Patch";
text(await tools.apply_patch(patch));
